#include <bits/stdc++.h>
using namespace std;
// a is 1-indexed (a[0] unused)
long long solve(const vector<long long>& a, int n) {
    vector<long long> suf(n + 4, 0);
    for (int i = n; i >= 1; --i) suf[i] = suf[i + 1] + max(0LL, a[i]);
    long long ans = 0;
    ans = max(ans, a[1] + suf[2]);  // card 1 is used
    ans = max(ans, suf[3]);         // cards 1 and 2 unused
    return ans;
}
int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        int n;
        scanf("%d", &n);
        vector<long long> a(n + 1);
        for (int i = 1; i <= n; ++i) scanf("%lld", &a[i]);
        printf("%lld\n", solve(a, n));
    }
}

