            }
            return blocks<=k;
        };
        int lo=0, hi=(int)cand.size()-1;       // find smallest feasible candidate
        while(lo<hi){
            int mid=(lo+hi)/2;
            if(ok(cand[mid])) hi=mid; else lo=mid+1;
        }
        printf("%lld\n", cand[lo]);
    }
