int n,k;
vector<int> a;
// can we get >= k disjoint pieces, each containing all of 0..m-1?
// Leftover elements can be merged into an adjacent piece without lowering its mex.
bool feasible(int m){
    if(m==0) return true;
    vector<int> cnt(m,0);
    int have=0, pieces=0;
    for(int i=0;i<n;i++){
        if(a[i]<m && cnt[a[i]]++==0) have++;
        if(have==m){ pieces++; fill(cnt.begin(),cnt.end(),0); have=0; }
    }
    return pieces>=k;
}
int main(){
    int t; if(scanf("%d",&t)!=1) return 0;
    while(t--){
        (void)scanf("%d %d",&n,&k);
        a.assign(n,0);
        for(auto& x:a) (void)scanf("%d",&x);
        int lo=0, hi=n/k;   // mex of each piece is at most (piece length) <= n/k when the min is taken over k pieces
        while(lo<hi){
            int mid=(lo+hi+1)/2;
            if(feasible(mid)) lo=mid; else hi=mid-1;
        }
        printf("%d\n", lo);
    }
}

