using namespace std;
int n, x, y;
// neighbours of vertex i (1-indexed) in the cycle plus the chord
vector<int> nb(int i){
    vector<int> r{ i % n + 1, (i - 2 + n) % n + 1 };
    if(i == x) r.push_back(y);
    if(i == y) r.push_back(x);
    return r;
}
bool valid(const vector<int>& a){
    for(int i = 1; i <= n; i++){
        set<int> s; for(int j : nb(i)) s.insert(a[j]);
        int m = 0; while(s.count(m)) m++;
        if(m != a[i]) return false;
    }
    return true;
}
int main(){
    int t; if(scanf("%d",&t)!=1) return 0;
    while(t--){
        (void)scanf("%d %d %d",&n,&x,&y);
        vector<int> a(n + 1);
        for(int i = 1; i <= n; i++) a[i] = (i - 1) % 2;   // alternate 0/1 around the cycle
        vector<int> ans;
        // try the few places where a single 2 can fix the conflicts
        vector<int> wrapFix = (n % 2 == 1) ? vector<int>{1, n} : vector<int>{0};
        vector<int> chordFix = ((y - x) % 2 == 0) ? vector<int>{x, y} : vector<int>{0};
        for(int w : wrapFix) for(int c : chordFix) {
            vector<int> b = a;
            if(w) b[w] = 2;
            if(c) b[c] = 2;
            if(valid(b)) { ans = b; break; }
        }
        if(ans.empty()) ans = a;   // should not happen, see notes
        for(int i = 1; i <= n; i++) printf("%d%c", ans[i], i == n ? '\n' : ' ');
    }
}

