        for(long long x=n; x>0; x/=3) d.push_back(x%3);
        int i = -1;
        for(int j=0;j<(int)d.size();j++) if(d[j]==2) i = j;   // most significant digit 2
        if(i < 0){ printf("%lld\n", n); continue; }   // already good
