        while(k < (int)d.size() && d[k] != 0) k++;
        if(k == (int)d.size()) d.push_back(0);
        for(int j=0;j<k;j++) d[j] = 0;                  // lower digits become zero
        d[k] = 1;                                        // raise digit k from 0 to 1
        long long m = 0, p = 1;
        for(int j=0;j<(int)d.size();j++){ m += d[j]*p; p *= 3; }
        printf("%lld\n", m);
    }
}

