int main(){
    int t; if(scanf("%d",&t)!=1) return 0;
    while(t--){
        int n; long long m; (void)scanf("%d %lld",&n,&m);
        long long V = 0;   // V = max over sequences of mex(S + {mex(S)})
        for(int i=0;i<n;i++){
            int l; (void)scanf("%d",&l);
            set<long long> s;
            for(int j=0;j<l;j++){ long long v; (void)scanf("%lld",&v); s.insert(v); }
            long long u=0; while(s.count(u)) u++;      // u = mex(S)
            long long w=u+1; while(s.count(w)) w++;    // mex(S + {u}) (w skips u itself)
            V = max(V, w);
        }
        // f(x) = max(x, V) for every x: one step reaches the best v from any start
        long long lim = min(m, V);
        long long total = (lim + 1) * V;               // x = 0..lim contribute V each
        if(m > V){
            // x = V+1..m contribute x itself
            long long a = V + 1, b = m;
            total += (a + b) * (b - a + 1) / 2;
        }
        printf("%lld\n", total);
    }
}

