int main(){
    int n; long long k1,k2;
    if(scanf("%d %lld %lld",&n,&k1,&k2)!=3) return 0;
    vector<long long> a(n), b(n);
    for(auto& x:a) (void)scanf("%lld",&x);
    for(auto& x:b) (void)scanf("%lld",&x);
    // only |a_i - b_i| matters; each operation (on either array) changes it by exactly 1
    priority_queue<long long> pq;
    for(int i=0;i<n;i++) pq.push(llabs(a[i]-b[i]));
    long long K = k1 + k2;
    for(long long op=0; op<K; op++){
        long long v = pq.top(); pq.pop();
        pq.push(llabs(v - 1));          // shrink the largest gap; a gap of 0 must grow to 1
    }
    long long err = 0;
    while(!pq.empty()){ long long v = pq.top(); pq.pop(); err += v * v; }
    printf("%lld\n", err);
}

