        vector<long long> c(n+1);
        for(int i=1;i<=n;i++) (void)scanf("%lld",&c[i]);
        // segment i is horizontal (x) for odd i and vertical (y) for even i.
        // Using k segments: odd-indexed ones must sum to n, even-indexed ones must sum to n.
        long long preO=0, preE=0, minO=LLONG_MAX, minE=LLONG_MAX;
        long long best=LLONG_MAX;
        for(int k=1;k<=n;k++){
            if(k%2==1){ preO+=c[k]; minO=min(minO,c[k]); }
            else      { preE+=c[k]; minE=min(minE,c[k]); }
            if(k<2) continue;
            long long o=(k+1)/2, e=k/2;                 // counts of odd and even indices up to k
            long long cost = preO + (n-o)*minO + preE + (n-e)*minE;
            best=min(best,cost);
        }
        printf("%lld\n", best);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; if(scanf("%d",&t)!=1) return 0;
    while(t--){
        int n; (void)scanf("%d",&n);
        vector<long long> a(n);
        for(auto& x:a) (void)scanf("%lld",&x);
        const long long NEG = LLONG_MIN / 4;
        long long S = 0;                                  // alternating sum (0-indexed: even +, odd -)
        for(int i=0;i<n;i++) S += (i%2==0 ? a[i] : -a[i]);
        long long best = S;                               // Alice may end at once
        for(int p=0;p<2;p++){                             // same-parity swap: gain r-l, sum unchanged
            int first=-1, last=-1;
            for(int i=p;i<n;i+=2){ if(first<0) first=i; last=i; }
            if(first>=0 && last>first) best = max(best, S + (long long)(last-first));
        }
        long long bestEvenL = NEG, bestOddL = NEG;        // max(-2a_l - l) over even l, max(2a_l - l) over odd l
        for(int r=0;r<n;r++){
            if(r%2==1){                                   // r odd (sign -), partner l even
                if(bestEvenL > NEG) best = max(best, S + bestEvenL + r + 2*a[r]);
                bestOddL = max(bestOddL, 2*a[r] - r);     // r becomes a left candidate for later even r
            } else {                                      // r even (sign +), partner l odd
                if(bestOddL > NEG) best = max(best, S + bestOddL + r - 2*a[r]);
                bestEvenL = max(bestEvenL, -2*a[r] - r);  // r becomes a left candidate for later odd r
            }
        }
        printf("%lld\n", best);
    }
}

#include <bits/stdc++.h>
using namespace std;
// Adding c numbers of the form 99..9 = 10^e - 1 gives R = (n - c) + 10*K, where K = sum a_e 10^(e-1)
// has decimal digit sum exactly c (c <= 7 < 10, so no carries in K). Answer is always <= 7.
// For each c, a small DP over the digits of K decides whether some K with digit sum c makes R contain a 7.
bool feasible(long long n, int c){
    long long X = n - c;
    int xd[16]={0};
    for(int p=0;p<16 && X>0;p++){ xd[p]=X%10; X/=10; }
    // state: carry, used digit-sum, found-7 flag
    static bool cur[2][8][2], nxt[2][8][2];
    memset(cur,0,sizeof(cur));
    // position 0: R_0 = X_0, no K digit involved
    cur[0][0][xd[0]==7] = true;
    for(int p=1;p<=13;p++){
        memset(nxt,0,sizeof(nxt));
        for(int car=0;car<2;car++) for(int u=0;u<=c;u++) for(int f=0;f<2;f++){
            if(!cur[car][u][f]) continue;
            int maxk = (p-1 <= 11) ? (c-u) : 0;   // K digit at position p-1
            for(int k=0;k<=maxk;k++){
                int s = xd[p] + k + car;
                int digit = s % 10, ncar = s / 10;
                nxt[ncar][u+k][f || digit==7] = true;
            }
        }
        memcpy(cur,nxt,sizeof(cur));
    }
    return cur[0][c][1] || cur[1][c][1];   // leftover carry beyond position 13 is impossible here
}
int main(){
    int t; if(scanf("%d",&t)!=1) return 0;
    while(t--){
        long long n; (void)scanf("%lld",&n);
        int ans = 0;
        while(ans < 8 && !feasible(n, ans)) ans++;
        printf("%d\n", ans);
    }
}

#include <bits/stdc++.h>
using namespace std;
struct DSU {
    vector<int> p, sz;
    DSU(int n): p(n), sz(n,1) { iota(p.begin(), p.end(), 0); }
    int find(int x){ while(p[x]!=x){ p[x]=p[p[x]]; x=p[x]; } return x; }
    bool unite(int a, int b){
        a=find(a); b=find(b);
        if(a==b) return false;
        if(sz[a]<sz[b]) swap(a,b);
        p[b]=a; sz[a]+=sz[b]; return true;
    }
};
int main(){
    int t; if(scanf("%d",&t)!=1) return 0;
    while(t--){
        int n,m1,m2; (void)scanf("%d %d %d",&n,&m1,&m2);
        vector<pair<int,int>> F(m1), G(m2);
        for(auto& e:F){ (void)scanf("%d %d",&e.first,&e.second); e.first--; e.second--; }
        for(auto& e:G){ (void)scanf("%d %d",&e.first,&e.second); e.first--; e.second--; }
        DSU dg(n), df(n);
        for(auto& e:G) dg.unite(e.first, e.second);
        int compG = 0;
        for(int i=0;i<n;i++) if(dg.find(i)==i) compG++;
        long long crossing = 0;
        for(auto& e:F){
            if(dg.find(e.first)!=dg.find(e.second)) crossing++;   // F edge joins two G-components: must delete it
            else df.unite(e.first, e.second);                       // keep it
        }
        int compF = 0;                                              // components of the kept F edges
        for(int i=0;i<n;i++) if(df.find(i)==i) compF++;
        // each G-component must be internally connected: add (compF - compG) edges
        printf("%lld\n", crossing + (long long)(compF - compG));
    }
}

#include <bits/stdc++.h>
using namespace std;
// segment tree over y = 1..n: value = floor(y/2) - (number of chosen free figures <= y); supports range add and range min
struct Seg {
    int n; vector<long long> mn, lz;
    void build(int node, int l, int r){
        lz[node]=0;
        if(l==r){ mn[node]=l/2; return; }
        int m=(l+r)/2; build(2*node,l,m); build(2*node+1,m+1,r);
        mn[node]=min(mn[2*node],mn[2*node+1]);
    }
    void add(int node,int l,int r,int ql,int qr,long long v){
        if(qr<l||r<ql) return;
        if(ql<=l&&r<=qr){ mn[node]+=v; lz[node]+=v; return; }
        int m=(l+r)/2;
        add(2*node,l,m,ql,qr,v); add(2*node+1,m+1,r,ql,qr,v);
        mn[node]=min(mn[2*node],mn[2*node+1])+lz[node];
    }
    long long query(int node,int l,int r,int ql,int qr){
        if(qr<l||r<ql) return LLONG_MAX/4;
        if(ql<=l&&r<=qr) return mn[node];
        int m=(l+r)/2;
        return min(query(2*node,l,m,ql,qr), query(2*node+1,m+1,r,ql,qr)) + lz[node];
    }
};
int main(){
    int t; if(scanf("%d",&t)!=1) return 0;
    while(t--){
        int n; (void)scanf("%d",&n);
        static char s[400005];
        (void)scanf("%s",s);
        // D[x] = number of visitable days in [x, n]
        vector<int> D(n+2,0);
        for(int x=n;x>=1;x--) D[x]=D[x+1]+(s[x-1]=='1');
        Seg seg; seg.n=n; seg.mn.assign(4*n+4,0); seg.lz.assign(4*n+4,0);
        seg.build(1,1,n);
        long long chosen=0, freeSum=0;
        for(int i=n;i>=1;i--){
            // figure i can be free if a day >= i is left for it (chosen+1 <= D[i]),
            // and every prefix keeps enough non-free partners below it
            if(chosen+1 <= D[i] && seg.query(1,1,n,i,n) >= 1){
                seg.add(1,1,n,i,n,-1);
                chosen++; freeSum+=i;
            }
        }
        long long total=(long long)n*(n+1)/2;
        printf("%lld\n", total-freeSum);
    }
}

