        long long M = X - Y;                       // leftovers of the big side that stay paired among themselves
        long long E = 0;
        for(int c=1;c<=n;c++) E += 2*(A[c]/2);     // same-colour pairs available within the big side
        long long cost = Y + M/2 + max(0LL, M-E)/2;
