// f(x,y) = (x|y) - y = x & ~y, so the value of [a1..an] is a1 & ~(a2|...|an).
// Only the first element matters: pick i maximising a_i & ~(OR of all other elements).
int main(){
    int n; if(scanf("%d",&n)!=1) return 0;
    vector<long long> a(n);
    for(auto& x:a) (void)scanf("%lld",&x);
    vector<long long> pre(n+1,0), suf(n+2,0);            // pre[i] = OR of a[0..i-1], suf[i] = OR of a[i..n-1]
    for(int i=0;i<n;i++) pre[i+1]=pre[i]|a[i];
    for(int i=n-1;i>=0;i--) suf[i]=suf[i+1]|a[i];
    int best=0; long long bestVal=-1;
    for(int i=0;i<n;i++){
        long long others = pre[i] | suf[i+1];
        long long v = a[i] & ~others;
        if(v>bestVal){ bestVal=v; best=i; }
    }
    printf("%lld", a[best]);
    for(int i=0;i<n;i++) if(i!=best) printf(" %lld", a[i]);
    printf("\n");
}

#include <bits/stdc++.h>
using namespace std;
// cnt[h] = number of all-ones contiguous blocks of length exactly h in a binary array
vector<long long> countBlocks(const vector<int>& v, int maxLen){
    vector<long long> cnt(maxLen+2, 0);
    int n = v.size(), i = 0;
    while(i < n){
        if(v[i] == 0){ i++; continue; }
        int j = i;
        while(j < n && v[j] == 1) j++;
        long long L = j - i;                       // a run of L ones
        for(long long h=1; h<=L && h<=maxLen; h++) cnt[h] += L - h + 1;
        i = j;
    }
    return cnt;
}
int main(){
    int n,m; long long k;
    if(scanf("%d %d %lld",&n,&m,&k)!=3) return 0;
    vector<int> a(n), b(m);
    for(auto& x:a) (void)scanf("%d",&x);
    for(auto& x:b) (void)scanf("%d",&x);
    vector<long long> ca = countBlocks(a, n), cb = countBlocks(b, m);
    long long ans = 0;
    // a subrectangle of height h and width w = k/h (all ones) is counted by ca[h]*cb[w]
    for(long long h=1; h<=n; h++){
        if(k % h) continue;
        long long w = k / h;
        if(w > m) continue;
        ans += ca[h] * cb[w];
    }
    printf("%lld\n", ans);
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; if(scanf("%d",&t)!=1) return 0;
    while(t--){
        int n; (void)scanf("%d",&n);
        vector<long long> a(n);
        for(auto& x:a) (void)scanf("%lld",&x);
        sort(a.begin(), a.end());
        // Mirror-symmetric polygon: all equal-length pairs as sides, plus up to two unpaired sides.
        long long P = 0; int pairs = 0;
        vector<long long> L;                       // leftover single sticks (one per odd-count value)
        for(int i=0;i<n;){
            int j=i; while(j<n && a[j]==a[i]) j++;
            long long cnt = j - i;
            pairs += cnt/2; P += (cnt/2) * 2 * a[i];
            if(cnt % 2) L.push_back(a[i]);
            i = j;
        }
        long long ans = 0;
        if(pairs == 0){ printf("0\n"); continue; }   // need at least one pair (and 3+ sides)
        if(pairs >= 2) ans = max(ans, P);             // no unpaired side: sides are all pairs (>= 4 sides)
        for(long long s : L) if(s < P) ans = max(ans, P + s);            // one unpaired side s: s < others
        for(size_t i=0; i+1<L.size(); i++)                                 // two unpaired sides s1<=s2: s2 - s1 < P
            if(L[i+1] - L[i] < P) ans = max(ans, P + L[i] + L[i+1]);
        printf("%lld\n", ans);
    }
}

#include <bits/stdc++.h>
using namespace std;
// one operation on current label x: every original letter currently labelled x moves to x-1
void opLabel(array<int,26>& lab, int x){
    for(int c=0;c<26;c++) if(lab[c]==x) lab[c]=x-1;
}
int main(){
    int t; if(scanf("%d",&t)!=1) return 0;
    while(t--){
        int n; long long k; (void)scanf("%d %lld",&n,&k);
        static char buf[200005];
        (void)scanf("%s",buf);
        string best;
        int maxT = (int)min<long long>(k, 25);
        for(int T=0; T<=maxT; T++){
            array<int,26> lab; for(int c=0;c<26;c++) lab[c]=c;
            long long rem = k;
            if(T>0){                                  // chain T..1: every letter <= T becomes 'a'
                for(int x=T;x>=1;x--) opLabel(lab,x);
                rem = k - T;
            }
            // first position whose letter is not 'a' now
            int first = -1;
            for(int i=0;i<n;i++) if(lab[buf[i]-'a']!=0){ first=lab[buf[i]-'a']; break; }
            if(first>0 && rem>0){                     // spend the rest on that letter, going down
                int x=first;
                while(rem>0 && x>0){ opLabel(lab,x); rem--; x--; }
            }
            string cand(n,'a');
            for(int i=0;i<n;i++) cand[i] = char('a' + lab[buf[i]-'a']);
            if(T==0 || cand<best) best = cand;
        }
        puts(best.c_str());
    }
}

