using namespace std;
// Each colour must form full bands: horizontal bands of >= 2 whole rows, or vertical bands of >= 2 whole columns.
// Horizontal: colour i can supply up to f_i = a_i / m rows (usable only if f_i >= 2). We need
// sum of rows = n with at most n/2 colours (each needs >= 2 rows) -> best is the top floor(n/2) values.
bool canBands(long long rows, long long cols, const vector<long long>& a){
    // rows: number of rows to cover, cols: row length; colour supplies floor(a_i / cols) rows
    vector<long long> f;
    for(long long x : a){ long long v = x / cols; if(v >= 2) f.push_back(v); }
    sort(f.rbegin(), f.rend());
    long long take = min<long long>(rows / 2, (long long)f.size());
    long long sum = 0;
    for(long long i=0;i<take;i++) sum += f[i];
    return sum >= rows;
}
int main(){
    int t; if(scanf("%d",&t)!=1) return 0;
    while(t--){
        long long n,m; int k;
        (void)scanf("%lld %lld %d",&n,&m,&k);
        vector<long long> a(k);
        for(auto& x:a) (void)scanf("%lld",&x);
        bool ok = canBands(n, m, a) || canBands(m, n, a);
        puts(ok ? "Yes" : "No");
    }
}

